mapper.select:
select sub.subject_id, sub.name,sc.student_id,sc.score from subjects sub
JOIN scores sc ON sub.subject_id = sc.subject_id


        AND sub.subject_id = #{subjectId}


order by sub.subject_id;

select  s.id ,s.name, sc.subject_id, sc.score from students s
JOIN scores  sc ON s.id = sc.student_id


        AND  s.id = #{studentId}


order by s.id;
